import React, { memo } from "react";
import { Box } from "@mui/material";
import Modal from "@mui/joy/Modal";
import ModalClose from "@mui/joy/ModalClose";
import Typography from "@mui/joy/Typography";
import Divider from "@mui/material/Divider";
import { useMediaQuery } from "@mui/material";

// Split content into smaller chunks for better performance
const FeaturesList = memo(() => (
   <ul className="p-5 mt-4 mb-6 space-y-4 list-disc list-inside bg-blue-50/80 rounded-xl">
      <li className="text-gray-700">
         <strong className="text-gray-900">Intuitive Dashboard</strong> - Upon logging
         in, you’ll be greeted by a sleek dashboard
         showcasing key statistics about your surveys. Track
         survey and response counts, view the latest surveys
         and responses, all in one place.
      </li>
      <li className="text-gray-700">
         <strong className="text-gray-900">Comprehensive Survey Management</strong> -
         Easily manage your surveys with our user-friendly
         interface. Update existing surveys, preview them
         before sharing, or delete them with just a click.
         Our dynamic card-based layout and pagination make
         navigating through your surveys a breeze.
      </li>
      <li className="text-gray-700">
         <strong className="text-gray-900">Customizable Survey Creation</strong> -
         Create surveys tailored to your needs with various
         question types including multiple choice,
         checkboxes, dropdowns, short answers, and
         paragraphs. Customize your surveys with titles,
         descriptions, images, and set expiry dates to
         control when responses are accepted.
      </li>
      <li className="text-gray-700">
         <strong className="text-gray-900">Share & Publish</strong> - Once your survey
         is ready, share it effortlessly by copying the
         survey link. Choose whether to publish your survey
         or keep it private – the choice is yours!
      </li>
      <li className="text-gray-700">
         <strong className="text-gray-900">Secure & User-Friendly</strong> - Our app is
         designed with you in mind, featuring a clean,
         user-friendly interface and robust security
         measures, including authentication and authorization
         to keep your data safe.
      </li>
   </ul>
));

const TechStack = memo(() => (
   <ul className="p-5 mt-4 space-y-3 list-disc list-inside bg-green-50/80 rounded-xl">
      <li className="text-gray-700">
         <strong className="text-gray-900">React JS</strong> for a dynamic and
         responsive frontend experience.
      </li>
      <li className="text-gray-700">
         <strong className="text-gray-900">Laravel</strong> for a robust and scalable
         backend solution.
      </li>
   </ul>
));

const AboutContent = memo(() => (
   <div className="p-6 overflow-auto">
      <Typography variant="body1" className="mb-8 leading-relaxed text-gray-700">
         Welcome to SurveyForm – a web application built with
         React JS and Laravel framework.
      </Typography>
      <Typography variant="h6" className="mt-2 mb-4 font-bold text-gray-900">
         Features
      </Typography>
      <FeaturesList />
      <Typography variant="h6" className="mt-6 mb-4 font-bold text-gray-900">
         Built With
      </Typography>
      <TechStack />
   </div>
));

const AboutPopup = memo(({ openAboutPopup, setOpenAboutPopup }) => {
   const handleClosePopup = () => setOpenAboutPopup(false);
   const isMobile = useMediaQuery("(max-width:600px)");

   const dynamicPopupStyle = {
      position: "absolute",
      top: "50%",
      left: "50%",
      transform: "translate(-50%, -50%)",
      width: "min(90%, 600px)",
      maxHeight: isMobile ? "95vh" : "calc(100vh - 100px)",
      padding: "16px",
      willChange: "transform", // Optimize for animations
      overflowY: "auto",
      overscrollBehavior: "contain", // Prevent scroll chaining
   };

   if (!openAboutPopup) return null;

   return (
      <Modal
         open={openAboutPopup}
         onClose={handleClosePopup}
         className="bg-black/20" // Replace backdrop-blur with simple overlay
         slotProps={{
            backdrop: {
               style: {
                  backgroundColor: 'rgba(0, 0, 0, 0.2)'
               }
            }
         }}
      >
         <Box
            sx={{
               ...dynamicPopupStyle,
               bgcolor: "background.paper",
               borderRadius: "12px",
               boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.25)",
            }}
            className="scrollbar-thin scrollbar-thumb-gray-400 scrollbar-track-transparent hover:scrollbar-thumb-gray-500"
         >
            <div className="sticky top-0 z-10 p-4 bg-white">
               <div className="absolute right-0 -top-3">
                  <ModalClose
                     variant="outlined"
                     onClick={handleClosePopup}
                     className="transition-colors hover:bg-red-50 hover:text-red-600"
                  />
               </div>
               <Typography variant="h5" className="mb-4 font-bold text-center text-gray-900">
                  About SurveyForm
               </Typography>
               <Divider className="opacity-50" />
            </div>
            <AboutContent />
         </Box>
      </Modal>
   );
});

FeaturesList.displayName = 'FeaturesList';
TechStack.displayName = 'TechStack';
AboutContent.displayName = 'AboutContent';
AboutPopup.displayName = 'AboutPopup';

export default AboutPopup;

import React, { memo, useMemo } from 'react';
import '@css/AnimatedBackground.css';

const AnimatedBackground = memo(() => {

   const lineColors = useMemo(() => {
      const colors = [];
      for (let i = 0; i < 12; i++) {
         colors.push(Math.random() < 0.5
            ? 'rgba(255, 0, 0, 0.2)' // Pure red with 20% opacity
            : 'rgba(0, 255, 0, 0.2)' // Pure green with 20% opacity
         );
      }
      return colors;
   }, []);

   return (
      <div className="fixed inset-0 animated-lines">
         {Array.from({ length: 12 }).map((_, index) => (
            <div
               key={index}
               className="line"
               style={{
                  backgroundColor: lineColors[index],
                  willChange: 'transform', // Performance hint for browsers
                  transform: 'translateZ(0)' // Force hardware acceleration
               }}
            />
         ))}
      </div>
   );
});

AnimatedBackground.displayName = 'AnimatedBackground';

export default AnimatedBackground;

import React from "react";
import { Breadcrumbs as MuiBreadcrumbs } from "@mui/material";
import { Link as RouterLink } from "react-router-dom";
import NavigateNextIcon from "@mui/icons-material/NavigateNext";

const Breadcrumbs = ({ links }) => {
   if (!links || links.length === 0) {
      return null;
   }

   return (
      <MuiBreadcrumbs
         separator={<NavigateNextIcon fontSize="small" />}
         aria-label="breadcrumb"
         className="dark:text-gray-400 text-slate-900 "
      >
         {links.map((link, index) => (
            <Link
               key={index}
               to={link.to}
               style={{
                  textDecoration: "none",
                  color:
                     index === links.length - 1 ? "inherit" : "#3498DB",
                  fontSize: "0.9rem",
               }}
               disabled={index === links.length - 1} // Disable the last link
            >
               {link.label}
            </Link>
         ))}
      </MuiBreadcrumbs>
   );
};

const Link = (props) => {
   if (props.disabled) {
      return <span {...props}>{props.children}</span>;
   }
   return <RouterLink {...props} />;
};

export default Breadcrumbs;

import React from 'react';
import { motion } from 'framer-motion';

export default function DashboardCard({ children, className = "", animationDelay = 0 }) {
   return (
      <motion.div
         initial={{ opacity: 0, y: 20 }}
         animate={{ opacity: 1, y: 0 }}
         transition={{
            duration: 0.5,
            delay: animationDelay,
            ease: "easeOut"
         }}
         whileHover={{
            y: -5,
            transition: { duration: 0.2 }
         }}
         className={`
                relative overflow-hidden
                bg-white rounded-xl
                border border-gray-100
                shadow-sm hover:shadow-md
                transition-all duration-200
                z-[var(--z-card)]
                hover:z-[var(--z-card-hover)]
                ${className}
            `}
      >
         {/* Gradient overlay */}
         <div className="absolute inset-0 bg-gradient-to-br from-transparent via-transparent to-gray-50/30" />

         {/* Card content */}
         <div className="relative z-[var(--z-card-content)]">
            {children}
         </div>
      </motion.div>
   );
}

import React, { useEffect, useState, useRef, useLayoutEffect, useCallback } from "react";
import { Navigate, NavLink, Outlet } from "react-router-dom";
import { useStateContext } from "@context/ContextProvider";
import axiosClient from "@api/axios";
import Toast from "@components/Toast";
import UserProfilePopup from "@components/UserProfilePopup";
import { Unstable_Popup as BasePopup } from "@mui/base/Unstable_Popup";
import logo from "@images/AceLogo.png";
import banner from "@images/AceBanner.png";
import { motion, AnimatePresence } from "framer-motion";
import {
   HomeIcon,
   ClipboardDocumentListIcon,
   Bars3Icon,
   XMarkIcon,
   ChevronLeftIcon,
   ChevronRightIcon
} from "@heroicons/react/24/outline";

// Simple polyfill for requestIdleCallback
const safeRequestIdleCallback = (callback) => {
   if (typeof window !== 'undefined' && window.requestIdleCallback) {
      return window.requestIdleCallback(callback);
   }
   // Fallback for Safari and other browsers
   return setTimeout(callback, 1);
};




export default function DefaultLayout() {
   const { currentUser, userToken, setCurrentUser, setUserToken } = useStateContext();
   const [isUserProfilePopupOpen, setIsUserProfilePopupOpen] = useState(false);
   const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
   const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(() => {
      try {
         const saved = localStorage.getItem('sidebar-collapsed');
         return saved ? JSON.parse(saved) : false;
      } catch {
         return false;
      }
   });
   const [isSidebarHovered, setIsSidebarHovered] = useState(false);
   const [isMobile, setIsMobile] = useState(() => {
      try {
         return typeof window !== 'undefined' ? window.innerWidth < 768 : false;
      } catch {
         return false;
      }
   });
   const [anchor, setAnchor] = useState(null);

   // Refs for cleanup

   const resizeTimeoutRef = useRef(null);
   const abortControllerRef = useRef(null);
   const cleanupRef = useRef([]);
   const sidebarRef = useRef(null);
   const contentRef = useRef(null);

   // Compute expanded state
   const shouldExpandSidebar = !isSidebarCollapsed || isSidebarHovered;

   // Direct DOM manipulation for sidebar animation
   const updateSidebarWidth = useCallback((expanded) => {
      if (sidebarRef.current && contentRef.current && !isMobile) {
         const width = expanded ? 256 : 64; // 16rem = 256px, 4rem = 64px

         // Use transform instead of width for better performance
         sidebarRef.current.style.width = `${width}px`;
         contentRef.current.style.marginLeft = `${width}px`;
      } else if (contentRef.current && isMobile) {
         // Reset margin on mobile
         contentRef.current.style.marginLeft = '0px';
      }
   }, [isMobile]);

   // Optimized event handlers
   const toggleMobileMenu = useCallback(() => {
      setIsMobileMenuOpen(prev => !prev);
   }, []);

   const closeMobileMenu = useCallback(() => {
      setIsMobileMenuOpen(false);
   }, []);

   const toggleSidebar = useCallback(() => {
      setIsSidebarCollapsed(prev => {
         const newState = !prev;
         updateSidebarWidth(!newState);

         // Use safe polyfill
         safeRequestIdleCallback(() => {
            try {
               localStorage.setItem('sidebar-collapsed', JSON.stringify(newState));
            } catch (error) {
               console.warn('Failed to save sidebar state:', error);
            }
         });
         return newState;
      });
   }, [updateSidebarWidth]);

   const handleSidebarMouseEnter = useCallback(() => {
      if (isSidebarCollapsed && !isMobile) {
         setIsSidebarHovered(true);
         updateSidebarWidth(true);
      }
   }, [isSidebarCollapsed, isMobile, updateSidebarWidth]);

   const handleSidebarMouseLeave = useCallback(() => {
      if (isSidebarHovered && !isMobile) {
         setIsSidebarHovered(false);
         updateSidebarWidth(false);
      }
   }, [isSidebarHovered, isMobile, updateSidebarWidth]);

   const handleClose = useCallback(() => {
      setIsUserProfilePopupOpen(false);
      setAnchor(null);
   }, []);

   const toggleUserProfilePopup = useCallback((event) => {
      setIsUserProfilePopupOpen(prev => !prev);
      setAnchor(event.currentTarget);
   }, []);

   // Initial sidebar setup
   useLayoutEffect(() => {
      updateSidebarWidth(shouldExpandSidebar);
   }, [shouldExpandSidebar, updateSidebarWidth]);

   // Optimized resize handler with mobile detection
   useLayoutEffect(() => {
      const handleResize = () => {
         try {
            const mobile = typeof window !== 'undefined' ? window.innerWidth < 768 : false;
            setIsMobile(mobile);

            if (resizeTimeoutRef.current) {
               clearTimeout(resizeTimeoutRef.current);
            }

            resizeTimeoutRef.current = setTimeout(() => {
               if (mobile) {
                  setIsMobileMenuOpen(false);
                  // Reset sidebar hover state on mobile
                  setIsSidebarHovered(false);
               } else {
                  // Re-apply sidebar width on desktop
                  updateSidebarWidth(shouldExpandSidebar);
               }
            }, 100);
         } catch (error) {
            console.warn('Resize handler error:', error);
         }
      };

      if (typeof window !== 'undefined') {
         window.addEventListener('resize', handleResize, { passive: true });
      }

      const cleanup = () => {
         if (typeof window !== 'undefined') {
            window.removeEventListener('resize', handleResize);
         }
         if (resizeTimeoutRef.current) {
            clearTimeout(resizeTimeoutRef.current);
         }
      };

      cleanupRef.current.push(cleanup);
      return cleanup;
   }, [shouldExpandSidebar, updateSidebarWidth]);

   // User data fetching
   useEffect(() => {
      if (!userToken) {

         return;
      }

      const controller = new AbortController();
      abortControllerRef.current = controller;
      axiosClient.get('/me', { signal: controller.signal })
         .then(({ data }) => {
            if (!controller.signal.aborted) setCurrentUser(data);
         })
         .catch(error => {
            if (!controller.signal.aborted) console.error('Error fetching user data:', error);
         });
      return () => controller.abort();
   }, [userToken, setCurrentUser]);

   // Logout handler
   const onLogout = useCallback(async (ev) => {
      ev.preventDefault();

      if (abortControllerRef.current) {
         abortControllerRef.current.abort();
      }

      const logoutController = new AbortController();

      try {
         await axiosClient.post("logout", {}, { signal: logoutController.signal });

         setCurrentUser({});
         setUserToken(null);



      } catch (error) {
         if (error.name !== 'AbortError') {
            console.error("Logout error:", error);
         }
      }
   }, [setCurrentUser, setUserToken]);

   // Outside click handler
   useEffect(() => {
      if (!anchor) return;

      const handleOutsideClick = (event) => {
         const target = event.target;
         if (anchor &&
            !anchor.contains(target) &&
            !target.closest(".action-popup") &&
            !target.closest("[data-popup]")) {
            setIsUserProfilePopupOpen(false);
            setAnchor(null);
         }
      };

      const timeoutId = setTimeout(() => {
         document.addEventListener("mousedown", handleOutsideClick, { passive: true });
      }, 50);

      const cleanup = () => {
         clearTimeout(timeoutId);
         document.removeEventListener("mousedown", handleOutsideClick);
      };

      cleanupRef.current.push(cleanup);
      return cleanup;
   }, [anchor]);

   // Master cleanup
   useEffect(() => {
      return () => {
         if (abortControllerRef.current) {
            abortControllerRef.current.abort();
         }

         cleanupRef.current.forEach(cleanup => {
            try {
               cleanup();
            } catch (error) {
               console.warn('Cleanup error:', error);
            }
         });
         cleanupRef.current = [];
      };
   }, []);

   if (!userToken) {
      return <Navigate to="login" />;
   }

   return (
      <div className="flex min-h-screen overflow-x-hidden">
         {/* Desktop Sidebar - Pure CSS Performance */}
         <aside
            ref={sidebarRef}
            className="fixed top-0 left-0 z-40 flex-col hidden h-screen overflow-hidden bg-white border-r border-gray-200 shadow-sm md:flex"
            style={{
               width: shouldExpandSidebar ? '256px' : '64px',
               transition: 'width 0.2s ease-out',
               willChange: 'width'
            }}
            onMouseEnter={handleSidebarMouseEnter}
            onMouseLeave={handleSidebarMouseLeave}
         >
            <div className="flex justify-center flex-shrink-0 p-2 border-b border-gray-200">
               <img
                  src={shouldExpandSidebar ? banner : logo}
                  alt="Ace Survey"
                  className="w-auto h-14"
                  loading="lazy"
               />
            </div>

            <nav className={`flex flex-col gap-2 flex-1 overflow-hidden ${!shouldExpandSidebar ? 'p-2' : 'p-4'}`}>
               <NavLink
                  to="/dashboard"
                  className={({ isActive }) =>
                     `flex items-center rounded-lg py-3 text-sm font-medium ${!shouldExpandSidebar ? 'px-2 justify-center' : 'px-4'
                     } ${isActive
                        ? "bg-blue-600 text-white shadow-md hover:bg-blue-700"
                        : "text-gray-600 hover:bg-gray-100 hover:text-gray-900"
                     }`
                  }
                  title={!shouldExpandSidebar ? "Dashboard" : ""}
               >
                  {({ isActive }) => (
                     <>
                        <HomeIcon className={`flex-shrink-0 w-5 h-5 ${isActive ? 'text-white' : 'text-gray-600'}`} />
                        {shouldExpandSidebar && (
                           <span className="ml-2 overflow-hidden whitespace-nowrap">
                              Dashboard
                           </span>
                        )}
                     </>
                  )}
               </NavLink>

               <NavLink
                  to="/surveys"
                  className={({ isActive }) =>
                     `flex items-center rounded-lg py-3 text-sm font-medium ${!shouldExpandSidebar ? 'px-2 justify-center' : 'px-4'
                     } ${isActive
                        ? "bg-blue-600 text-white shadow-md hover:bg-blue-700"
                        : "text-gray-600 hover:bg-gray-100 hover:text-gray-900"
                     }`
                  }
                  title={!shouldExpandSidebar ? "Surveys" : ""}
               >
                  {({ isActive }) => (
                     <>
                        <ClipboardDocumentListIcon className={`flex-shrink-0 w-5 h-5 ${isActive ? 'text-white' : 'text-gray-600'}`} />
                        {shouldExpandSidebar && (
                           <span className="ml-2 overflow-hidden whitespace-nowrap">
                              Surveys
                           </span>
                        )}
                     </>
                  )}
               </NavLink>
            </nav>

            {shouldExpandSidebar && (
               <footer className="flex-shrink-0 p-3 border-t border-gray-200">
                  <div className="text-xs text-center text-gray-500">
                     © 2024 Ace Survey
                  </div>
               </footer>
            )}
         </aside>

         {/* Mobile Sidebar - Simplified */}
         <AnimatePresence mode="wait">
            {isMobileMenuOpen && (
               <>
                  <motion.aside
                     initial={{ x: -320 }}
                     animate={{ x: 0 }}
                     exit={{ x: -320 }}
                     transition={{ duration: 0.15, ease: "easeOut" }}
                     className="fixed inset-y-0 left-0 z-50 w-80 max-w-[85vw] bg-white shadow-xl md:hidden flex flex-col"
                  >
                     <div className="p-4 border-b border-gray-200">
                        <img src={banner} alt="Ace Survey" className="w-auto mx-auto h-14" loading="lazy" />
                     </div>
                     <nav className="flex flex-col flex-1 gap-1 p-3 overflow-y-auto">
                        <NavLink
                           to="/dashboard"
                           onClick={closeMobileMenu}
                           className={({ isActive }) =>
                              `flex items-center gap-3 px-4 py-3 text-sm font-medium rounded-lg ${isActive ? "bg-blue-600 text-white" : "text-gray-600 hover:bg-gray-100"
                              }`
                           }
                        >
                           <HomeIcon className="w-5 h-5" />
                           <span>Dashboard</span>
                        </NavLink>
                        <NavLink
                           to="/surveys"
                           onClick={closeMobileMenu}
                           className={({ isActive }) =>
                              `flex items-center gap-3 px-4 py-3 text-sm font-medium rounded-lg ${isActive ? "bg-blue-600 text-white" : "text-gray-600 hover:bg-gray-100"
                              }`
                           }
                        >
                           <ClipboardDocumentListIcon className="w-5 h-5" />
                           <span>Surveys</span>
                        </NavLink>
                     </nav>
                  </motion.aside>
                  <motion.div
                     initial={{ opacity: 0 }}
                     animate={{ opacity: 0.5 }}
                     exit={{ opacity: 0 }}
                     transition={{ duration: 0.15 }}
                     className="fixed inset-0 z-40 bg-black md:hidden"
                     onClick={closeMobileMenu}
                  />
               </>
            )}
         </AnimatePresence>

         {/* Main Content - Pure CSS */}
         <div
            ref={contentRef}
            className="flex flex-col flex-1 min-w-0"
            style={{
               marginLeft: isMobile ? '0px' : (shouldExpandSidebar ? '256px' : '64px'),
               transition: 'margin-left 0.2s ease-out',
               willChange: 'margin-left'
            }}
         >
            <header className="sticky top-0 z-30 flex items-center justify-between px-4 py-3 border-b border-gray-200 shadow-sm bg-white/95 backdrop-blur-sm md:px-6">
               <div className="flex items-center gap-3">
                  <button
                     onClick={toggleMobileMenu}
                     className="p-2 text-gray-600 transition-colors duration-150 rounded-lg md:hidden hover:bg-gray-100"
                     type="button"
                     aria-label="Toggle mobile menu"
                  >
                     {isMobileMenuOpen ? <XMarkIcon className="w-6 h-6" /> : <Bars3Icon className="w-6 h-6" />}
                  </button>

                  <button
                     onClick={toggleSidebar}
                     className="hidden p-2 text-gray-600 transition-colors duration-150 rounded-lg md:block hover:bg-gray-100"
                     type="button"
                     aria-label={isSidebarCollapsed ? "Expand sidebar" : "Collapse sidebar"}
                  >
                     {isSidebarCollapsed ? <ChevronRightIcon className="w-5 h-5" /> : <ChevronLeftIcon className="w-5 h-5" />}
                  </button>

                  <div>
                     <div className="hidden md:block">
                        <h1 className="text-lg font-semibold text-gray-800">Ace Surveys</h1>
                        <p className="text-xs text-gray-500">Survey Management Platform</p>
                     </div>
                     <h1 className="text-lg font-semibold text-gray-800 md:hidden">Ace Survey</h1>
                  </div>
               </div>

               <div className="flex items-center gap-3">
                  <div className="items-center hidden gap-2 px-3 py-2 text-sm rounded-lg md:flex bg-gray-50">
                     <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                     <span className="font-medium">{currentUser.name}</span>
                  </div>
                  <button
                     onClick={toggleUserProfilePopup}
                     className="relative p-1 transition-transform duration-150 rounded-full hover:scale-105"
                     type="button"
                     aria-label="User profile"
                  >
                     <img
                        src={currentUser.avatar || logo}
                        alt="Profile"
                        className="w-10 h-10 transition-all duration-150 rounded-full ring-2 ring-gray-100 hover:ring-blue-200"
                        loading="lazy"
                        onError={(e) => {
                           e.target.onerror = null;
                           e.target.src = logo;
                        }}
                     />
                     <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 border-2 border-white rounded-full"></div>
                  </button>
               </div>
            </header>

            <main className="flex-1 p-4 overflow-x-hidden md:p-6 bg-gradient-to-br from-gray-50 to-gray-100">
               <Outlet />
            </main>
         </div>

         <Toast />

         {isUserProfilePopupOpen && (
            <BasePopup
               id="user-profile-popup"
               open={isUserProfilePopupOpen}
               anchor={anchor}
               placement="bottom-end"
               offset={8}
               onClose={handleClose}
            >
               <div className="action-popup" data-popup>
                  <UserProfilePopup onLogout={onLogout} />
               </div>
            </BasePopup>
         )}
      </div>
   );
}

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ExclamationTriangleIcon, XMarkIcon } from "@heroicons/react/24/outline";

const DeleteConfirmationModal = ({ isOpen, onConfirm, onCancel, title, message, confirmText, cancelText }) => {
   return (
      <AnimatePresence>
         {isOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center px-4 bg-black bg-opacity-50 backdrop-blur-sm">
               <motion.div
                  initial={{ opacity: 0, scale: 0.9, y: 20 }}
                  animate={{ opacity: 1, scale: 1, y: 0 }}
                  exit={{ opacity: 0, scale: 0.9, y: 20 }}
                  transition={{ duration: 0.2 }}
                  className="relative w-full max-w-md mx-4 bg-white rounded-lg shadow-2xl"
               >
                  {/* Close Button */}
                  <button
                     onClick={onCancel}
                     className="absolute top-3 right-3 p-1.5 text-gray-400 hover:text-gray-600 transition-colors duration-200 rounded-lg hover:bg-gray-100"
                  >
                     <XMarkIcon className="w-5 h-5" />
                  </button>

