export default function PaginationLinks({ meta, onPageClick }) {
   function onClick(ev, link) {
      ev.preventDefault();
      if (!link.url) {
         return;
      }
      onPageClick(link);
   }

   return (
      <motion.div
         initial={{ opacity: 0, y: 20 }}
         animate={{ opacity: 1, y: 0 }}
         className="flex items-center justify-between px-4 py-3 mt-8 transition-shadow duration-200 bg-white border border-gray-200 rounded-lg shadow-sm hover:shadow-md sm:px-6"
      >
         {/* Mobile pagination */}
         <div className="flex justify-between flex-1 sm:hidden">
            <motion.a
               whileHover={{ scale: 1.02 }}
               whileTap={{ scale: 0.98 }}
               href="#"
               onClick={(ev) => onClick(ev, meta.links[0])}
               className="relative inline-flex items-center px-4 py-2 text-sm font-medium text-gray-700 transition-colors bg-white border border-gray-300 rounded-md hover:bg-gray-50 hover:border-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
            >
               Previous
            </motion.a>
            <motion.a
               whileHover={{ scale: 1.02 }}
               whileTap={{ scale: 0.98 }}
               href="#"
               onClick={(ev) => onClick(ev, meta.links[meta.links.length - 1])}
               className="relative inline-flex items-center px-4 py-2 ml-3 text-sm font-medium text-gray-700 transition-colors bg-white border border-gray-300 rounded-md hover:bg-gray-50 hover:border-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
            >
               Next
            </motion.a>
         </div>

         {/* Desktop pagination */}
         <div className="hidden sm:flex sm:flex-1 sm:items-center sm:justify-between">
            <div>
               <p className="text-sm text-gray-700">
                  Showing <span className="font-medium text-gray-900">{meta.from}</span>{" "}
                  to <span className="font-medium text-gray-900">{meta.to}</span> of{" "}
                  <span className="font-medium text-gray-900">{meta.total}</span>{" "}
                  results
               </p>
            </div>
            <div>
               {meta.total > meta.per_page && (
                  <nav
                     aria-label="Pagination"
                     className="inline-flex space-x-1 rounded-md shadow-sm isolate"
                  >
                     {meta.links && meta.links.map((link, ind) => (
                        <motion.a
                           whileHover={{ scale: 1.05 }}
                           whileTap={{ scale: 0.95 }}
                           href="#"
                           onClick={(ev) => onClick(ev, link)}
                           key={ind}
                           aria-current={link.active ? 'page' : undefined}
                           className={`
                                        relative inline-flex items-center py-2 text-sm font-medium
                                        transition-all duration-200
                                        focus:z-20 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2
                                        ${link.label.includes("Previous") || link.label.includes("Next")
                                 ? "px-2 bg-gray-100 rounded-full hover:bg-gray-200"
                                 : "px-4"
                              }
                                        ${ind === 0 ? "rounded-l-lg" : ""}
                                        ${ind === meta.links.length - 1 ? "rounded-r-lg" : ""}
                                        ${link.active
                                 ? "bg-blue-600 text-white hover:bg-blue-700"
                                 : "text-gray-700 hover:bg-gray-100"
                              }
                                        ${!link.url ? "opacity-50 cursor-not-allowed" : "hover:opacity-90"}
                                    `}
                        >
                           {link.label.includes("Previous") && (
                              <ChevronLeftIcon className="w-5 h-5" aria-hidden="true" />
                           )}
                           {link.label.includes("Next") && (
                              <ChevronRightIcon className="w-5 h-5" aria-hidden="true" />
                           )}
                           {!link.label.includes("Previous") && !link.label.includes("Next") && (
                              <span dangerouslySetInnerHTML={{ __html: link.label }} />
                           )}
                        </motion.a>
                     ))}
                  </nav>
               )}
            </div>
         </div>
      </motion.div>
   );
}

import React from "react";
import { motion } from "framer-motion";

export default function PublicQuestionView({ question, index, answerChanged }) {
   let selectedOptions = [];

   function onCheckboxChanged(option, $event) {
      if ($event.target.checked) {
         selectedOptions.push(option.text);
      } else {
         selectedOptions = selectedOptions.filter(
            (op) => op !== option.text
         );
      }
      answerChanged(selectedOptions);
   }

   const inputBaseClass = "w-full transition-all duration-200 border border-gray-200 rounded-lg focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500";

   return (
      <motion.div
         initial={{ opacity: 0, y: 20 }}
         animate={{ opacity: 1, y: 0 }}
         transition={{ delay: index * 0.1 }}
         className="p-6 my-4 transition-shadow duration-200 bg-white border border-gray-200 shadow-sm rounded-xl hover:shadow-md"
      >
         <fieldset>
            <div className="flex items-start gap-3 mb-4">
               <span className="flex items-center justify-center w-6 h-6 text-sm font-semibold text-white bg-blue-600 rounded-full shrink-0">
                  {index + 1}
               </span>
               <div>
                  <legend className="text-lg font-semibold text-gray-900">
                     {question.question}
                  </legend>
                  {question.description && (
                     <p className="mt-2 text-sm text-gray-500">
                        {question.description}
                     </p>
                  )}
               </div>
            </div>

            <div className="mt-4 ml-9">
               {question.type === "dropdown" && (
                  <select
                     onChange={(ev) => answerChanged(ev.target.value)}
                     className={`${inputBaseClass} px-4 py-2.5 bg-white cursor-pointer hover:border-blue-200`}
                  >
                     <option value="">Please Select</option>
                     {question.data.options.map((option) => (
                        <option key={option.uuid} value={option.text}>
                           {option.text}
                        </option>
                     ))}
                  </select>
               )}

               {question.type === "multiple choice" && (
                  <div className="space-y-2">
                     {question.data.options.map((option) => (
                        <label
                           key={option.uuid}
                           className="flex items-center p-3 transition-colors duration-200 border border-gray-100 rounded-lg hover:bg-gray-50"
                        >
                           <input
                              id={option.uuid}
                              name={"question" + question.id}
                              value={option.text}
                              onChange={(ev) => answerChanged(ev.target.value)}
                              type="radio"
                              className="w-5 h-5 text-blue-600 transition-colors duration-200 border-2 border-gray-300 rounded-full cursor-pointer focus:ring-blue-500 focus:ring-offset-0"
                           />
                           <span className="ml-3 font-medium text-gray-700">
                              {option.text}
                           </span>
                        </label>
                     ))}
                  </div>
               )}

               {question.type === "checkboxes" && (
                  <div className="space-y-2">
                     {question.data.options.map((option) => (
                        <label
                           key={option.uuid}
                           className="flex items-center p-3 transition-colors duration-200 border border-gray-100 rounded-lg hover:bg-gray-50"
                        >
                           <input
                              id={option.uuid}
                              onChange={(ev) => onCheckboxChanged(option, ev)}
                              type="checkbox"
                              className="w-5 h-5 text-blue-600 transition-colors duration-200 border-2 border-gray-300 rounded cursor-pointer focus:ring-blue-500 focus:ring-offset-0"
                           />
                           <span className="ml-3 font-medium text-gray-700">
                              {option.text}
                           </span>
                        </label>
                     ))}
                  </div>
               )}

               {question.type === "short answer" && (
                  <input
                     type="text"
                     onChange={(ev) => answerChanged(ev.target.value)}
                     placeholder="Your answer"
                     className={`${inputBaseClass} px-4 py-2.5`}
                  />
               )}

               {question.type === "paragraph" && (
                  <textarea
                     onChange={(ev) => answerChanged(ev.target.value)}
                     rows={4}
                     placeholder="Your answer"
                     className={`${inputBaseClass} px-4 py-2.5 resize-none`}
                  />
               )}
            </div>
         </fieldset>
      </motion.div>
   );
}

import React, { useEffect, useState } from "react";
import { useStateContext } from "@context/ContextProvider";
import {
   TrashIcon,
   ChevronDownIcon,
   PlusCircleIcon,
   XMarkIcon,
} from "@heroicons/react/24/outline";
import { v4 as uuidv4 } from "uuid";
import { Divider } from "@mui/material";
import Tooltip from "@mui/material/Tooltip";
import Fade from "@mui/material/Fade";
import Select from "react-select";
import {
   FaAlignJustify,
   FaGripLines,
   FaRegCheckSquare,
   FaRegCircle,
   FaSortDown,
} from "react-icons/fa";
import { HiBars2 } from "react-icons/hi2";
import { motion } from "framer-motion";

export default function QuestionEditor({
   index = 0,
   question,
   addQuestion,
   deleteQuestion,
   questionChange,
}) {
   const [model, setModel] = useState({ ...question });
   const { questionTypes } = useStateContext();

   useEffect(() => {
      questionChange(model);
   }, [model]);

   function upperCaseFirst(str) {
      return str.charAt(0).toUpperCase() + str.slice(1);
   }

   function shouldHaveOptions(type = null) {
      type = type || model.type;
      return ["dropdown", "multiple choice", "checkboxes"].includes(type);
   }

   function onTypeChange(option) {
      const newModel = {
         ...model,
         type: option.value,
      };
      if (!shouldHaveOptions(model.type) && shouldHaveOptions(option.value)) {
         if (!model.data.options) {
            newModel.data = {
               options: [{ uuid: uuidv4(), text: "" }],
            };
         }
      }
      setModel(newModel);
   }

   function addOption() {
      model.data.options.push({
         uuid: uuidv4(),
         text: "",
      });
      setModel({ ...model });
   }

   function deleteOption(op) {
      model.data.options = model.data.options.filter(
         (option) => option.uuid !== op.uuid
      );
      setModel({ ...model });
   }

   const questionTypeOptions = questionTypes.map((type) => ({
      value: type,
      label: (
         <div className="flex items-center cursor-pointer">
            {getIcon(type)}
            <span className="ml-2">{upperCaseFirst(type)}</span>
         </div>
      ),
   }));

   function getIcon(type) {
      switch (type) {
         case "short answer":
            return <FaGripLines className="w-4 h-4" />;
         case "paragraph":
            return <FaAlignJustify className="w-4 h-4" />;
         case "checkboxes":
            return <FaRegCheckSquare className="w-4 h-4" />;
         case "multiple choice":
            return <FaRegCircle className="w-4 h-4" />;
         case "dropdown":
            return <FaSortDown className="w-4 h-4" />;
         default:
            return null;
      }
   }

   const customStyles = {
      control: (provided, state) => ({
         ...provided,
         minHeight: "38px",
         cursor: "pointer",
         borderColor: state.isFocused ? '#3b82f6' : '#e5e7eb',
         boxShadow: state.isFocused ? '0 0 0 1px #3b82f6' : 'none',
         '&:hover': {
            borderColor: '#3b82f6'
         }
      }),
      option: (provided, state) => ({
         ...provided,
         backgroundColor: state.isSelected ? '#3b82f6' : state.isFocused ? '#e5e7eb' : 'white',
         color: state.isSelected ? 'white' : '#374151',
         cursor: 'pointer',
         '&:active': {
            backgroundColor: '#2563eb'
         }
      }),
      menu: (provided) => ({
         ...provided,
         boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)',
         borderRadius: '0.5rem'
      }),
      valueContainer: (provided) => ({
         ...provided,
         padding: '0 12px'
      }),
      input: (provided) => ({
         ...provided,
         margin: '0'
      }),
      indicatorSeparator: () => ({
         display: 'none'
      }),
      indicatorsContainer: (provided) => ({
         ...provided,
         height: '38px'
      })
   };

   return (
      <motion.div
         initial={{ opacity: 0, y: 20 }}
         animate={{ opacity: 1, y: 0 }}
         transition={{ duration: 0.3 }}
         className="p-6 my-4 transition-shadow duration-200 bg-white border border-gray-200 shadow-sm rounded-xl hover:shadow-md"
      >
         <div className="flex flex-col justify-between gap-4 lg:flex-row">
            {/* Question Text */}
            <div className="flex w-full">
               <span className="flex items-center self-center justify-center w-8 h-8 mr-3 text-sm font-semibold text-white bg-blue-600 rounded-full">
                  {index + 1}
               </span>
               <input
                  type="text"
                  name="question"
                  placeholder="Question"
                  value={model.question}
                  onChange={(ev) => setModel({ ...model, question: ev.target.value })}
                  className="w-full px-4 py-2 text-gray-900 transition-all duration-200 border border-gray-200 rounded-lg focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 hover:border-blue-200"
               />
            </div>

            {/* Question Type */}
            <div className="relative min-w-[12rem] lg:w-1/3">
               <Select
                  value={questionTypeOptions.find(option => option.value === model.type)}
                  onChange={onTypeChange}
                  options={questionTypeOptions}
                  styles={customStyles}
                  className="text-sm"
                  isSearchable={false}
               />
            </div>
         </div>

         {shouldHaveOptions() && (
            <motion.div
               initial={{ opacity: 0 }}
               animate={{ opacity: 1 }}
               className="mt-6 space-y-3"
            >
               {model.data.options.length === 0 && (
                  <div className="p-4 text-sm text-center text-gray-500 rounded-lg bg-gray-50">
                     No options defined yet
