               )}

               {model.data.options.map((op, ind) => (
                  <motion.div
                     key={op.uuid}
                     initial={{ opacity: 0, x: -20 }}
                     animate={{ opacity: 1, x: 0 }}
                     className="flex items-center gap-2"
                  >
                     {model.type === "multiple choice" && (
                        <div className="flex items-center justify-center w-6 h-6">
