                           >
                              <QRCodeSVG
                                 ref={qrRef}
                                 value={shareLink}
                                 size={isMobile ? 200 : 250}
                                 level="H"
                                 includeMargin={true}
                                 imageSettings={{
                                    src: acelogo,
                                    height: isMobile ? 40 : 50,
                                    width: isMobile ? 40 : 50,
                                    excavate: true,
                                 }}
