      setNewEmail("");
      setNewEmailConfirmation("");
   };

   // For forms, make sure to call preventDefault immediately
   const onSubmitPassword = (e) => {
      e.preventDefault();
      handleChangePassword(e);
   };

   const onSubmitEmail = (e) => {
      e.preventDefault();
      handleChangeEmail(e);
   };

   return (
