export default function Surveys() {
   const {
      filteredSurveys,
      meta,
      loading,
      error,
      searchTerm,
      refreshing,
      getSurveys,
      handleSearch,
      deleteSurvey,
      refresh
   } = useSurveys();

   const { isOpen, surveyToDelete, openModal, closeModal } = useDeleteModal();

   const handlePageClick = useCallback((link) => {
      getSurveys(link.url);
   }, [getSurveys]);

   const handleDeleteConfirm = useCallback(async () => {
      if (!surveyToDelete) return;

      closeModal();
      try {
         await deleteSurvey(surveyToDelete);
      } catch (error) {
         // Error handling is done in the hook
      }
   }, [surveyToDelete, deleteSurvey, closeModal]);

   const breadcrumbLinks = [
      { to: "/dashboard", label: "Home" },
      { to: "", label: "Survey List" },
   ];

   // Render error state
   if (error && !loading && filteredSurveys.length === 0) {
      return <ErrorState error={error} onRetry={refresh} />;
   }

   return (
      <motion.div
         initial={{ opacity: 0 }}
         animate={{ opacity: 1 }}
         className="w-full mx-auto xl:w-11/12"
      >
         {/* Header Section */}
         <motion.div
            initial={{ y: -20, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            className="flex flex-col gap-6 mb-8 md:flex-row md:items-center md:justify-between"
         >
            <div className="flex flex-col justify-center">
               <h1 className="text-2xl font-bold text-gray-900">Survey List</h1>
               <Breadcrumbs links={breadcrumbLinks} />
            </div>

            <div className="flex flex-col gap-4 md:flex-row md:items-center">
               <div className="w-full md:w-64">
                  <SearchBar
                     searchTerm={searchTerm}
                     onSearch={handleSearch}
                     placeholder="Search surveys..."
                  />
               </div>

               <div className="flex gap-2">
                  <button
                     onClick={refresh}
                     disabled={loading || refreshing}
                     className="p-2.5 text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50"
                  >
                     <ArrowPathIcon className={`w-5 h-5 ${refreshing ? 'animate-spin' : ''}`} />
                  </button>

                  <Link
                     to="/surveys/create"
                     className="flex items-center justify-center gap-2 px-4 py-2.5 font-medium text-white transition-all duration-200 bg-blue-600 rounded-lg hover:bg-blue-700 hover:text-white focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
                  >
                     <PlusCircleIcon className="w-5 h-5" />
                     <span className="hidden md:inline-block">Create New Survey</span>
                  </Link>
               </div>
            </div>
         </motion.div>

         {/* Content */}
         {loading && !refreshing ? (
            <LoadingSkeleton />
         ) : (
            <SurveyGrid
               surveys={filteredSurveys}
               meta={meta}
               searchTerm={searchTerm}
               onDeleteClick={openModal}
               onPageClick={handlePageClick}
               refreshing={refreshing}
            />
         )}

         {/* Delete Confirmation Modal */}
         <DeleteModal
            isOpen={isOpen}
            onConfirm={handleDeleteConfirm}
            onCancel={closeModal}
            title="Delete Survey"
            message="Are you sure you want to delete this survey? This action cannot be undone."
         />
      </motion.div>
   );
}

import React, { useEffect, Suspense } from "react";
import { useLocation } from "react-router-dom";
import "@css/main.css";
import { createBrowserRouter, Navigate } from "react-router-dom";
const GuestLayout = React.lazy(() => import("@components/GuestLayout"));
const Login = React.lazy(() => import("@pages/Login"));
const Signup = React.lazy(() => import("@pages/Signup"));
const DefaultLayout = React.lazy(() => import("@components/DefaultLayout"));
const Dashboard = React.lazy(() => import("@pages/Dashboard"));
const Surveys = React.lazy(() => import("@pages/Surveys"));
const SurveyView = React.lazy(() => import("@pages/SurveyView"));
const SurveyPublicView = React.lazy(() => import("@pages/SurveyPublicView"));
const SurveyResponse = React.lazy(() => import("@pages/SurveyResponse"));
const Respondent = React.lazy(() => import("@pages/Respondent"));
const ForgotPassword = React.lazy(() => import("@pages/ForgotPassword"));
const ResetPassword = React.lazy(() => import("@pages/ResetPassword"));
const NotFound = React.lazy(() => import("@pages/NotFound"));
const Qr = React.lazy(() => import("@pages/Qr"))
const SurveySelection = React.lazy(() => import("@pages/SurveySelection"));

// Import the custom loading spinner with animation
import Loading from '@components/Loading';

const capitalizeFirstLetter = (string) => {
   return string.replace(/\b\w/g, char => char.toUpperCase());
};

const DynamicTitle = ({ children }) => {
   const location = useLocation();

   useEffect(() => {
      const path = location.pathname;
      let title = ""; // Default title

      if (path === "/login") {
         title = "Login";
      } else if (path === "/signup") {
         title = "Signup";
      } else if (path === "/dashboard") {
         title = "Dashboard";
      } else if (path === "/surveys") {
         title = "Surveys";
      } else if (path === "/surveys/create") {
         title = "Survey Create";
      } else if (path.startsWith("/survey/public/")) {
         const slug = path.split("/")[3].replace(/-/g, ' ');
         title = `${capitalizeFirstLetter(slug)} Survey`;
      } else if (path.startsWith("/surveys/")) {
         if (path.includes("/responses")) {
            title = "Survey Responses";
         } else if (path.match(/^\/surveys\/\d+$/)) {
            title = "Survey Edit";
         } else {
            title = "Survey View";
         }
      } else if (path === "/forgot-password") {
         title = "Forgot Password";
      } else if (path.startsWith("/reset-password/")) {
         title = "Reset Password";
      } else if (path === "/404") {
         title = "404 - Page Not Found";
      }
      else if (path === "/qr") {
         title = "QR Code";
      }
      else if (path === "/survey-selection") {
         title = "Select Survey";
      }


      document.title = title;
   }, [location]);

   return children;
};

const router = createBrowserRouter([
   {
      path: "/",
      element: (
         <Suspense fallback={<Loading />}>
            <DynamicTitle>
               <DefaultLayout />
            </DynamicTitle>
         </Suspense>
      ),
      children: [
         {
            index: true,
            element: <Navigate to="/dashboard" replace />,
         },
         {
            path: "/dashboard",
            element: <Dashboard />,
         },
         {
            path: "/surveys",
            element: <Surveys />,
         },
         {
            path: "/surveys/create",
            element: <SurveyView />,
         },
         {
            path: "/surveys/:id",
            element: <SurveyView />,
         },
         {
            path: "/surveys/:id/responses",
            element: <SurveyResponse />,
         },
         {
            path: "/surveys/:surveyId/responses/:responseId",
            element: <Respondent />,
         },


      ],
   },
   {
      path: "/",
      element: (
         <Suspense fallback={<Loading />}>
            <DynamicTitle>
               <GuestLayout />
            </DynamicTitle>
         </Suspense>
      ),
      children: [
         {
            path: "/login",
            element: <Login />,
         },
         {
            path: "/signup",
            element: <Signup />,
         },
         {
            path: "/forgot-password",
            element: <ForgotPassword />,
         },
         {
            path: "/reset-password/:token",
            element: <ResetPassword />,
         },
         {
            path: "/qr",
            element: <Qr />,
         },
         {
            path: "/survey-selection",
            element: <SurveySelection />,
         }
      ],
   },
   {
      path: "/survey/public/:slug",
      element: (
         <Suspense fallback={<Loading />}>
            <DynamicTitle>
               <SurveyPublicView />
            </DynamicTitle>
         </Suspense>
      ),
   },
   {
      path: "*",
      element: (
         <Suspense fallback={<Loading />}>
            <DynamicTitle>
               <NotFound />
            </DynamicTitle>
         </Suspense>
      ),
   },
]);

export default router;

